/* eslint-disable no-restricted-globals */

/**
 * The service worker.
 *
 * Its one job is that **the app opens with no network**. A crew arriving at a
 * call in a valley must get the live screens, not a dinosaur — and everything
 * they then record goes to IndexedDB, which needs no network either.
 *
 * Deliberately hand-written rather than generated by Workbox. What it has to do
 * is two caching rules and a version bump, and a build-time plugin would add a
 * dependency, a build step and a generated file to review in exchange for
 * indirection over forty lines.
 *
 * **API responses are never cached.** A crew shown a stale board or a stale run
 * would be worse than a crew shown nothing: the device's own IndexedDB copy is
 * the offline story, and it is authoritative. This caches the *shell* only.
 *
 * `?dev=1` on the registration URL (see registerSW.ts) flags a Vite dev server,
 * where the "shell" is unbundled source that changes on every save — caching it
 * would just mean editing a file and not seeing the edit. `DEV` below gates only
 * that caching; `push`/`notificationclick` are unconditional, so Web Push is
 * still testable from `docker compose up`.
 */

// Bumped on every deploy of the shell. An old cache is deleted on activate, so
// this is the only thing that has to be remembered when changing what is cached.
//
// v2: manifest.webmanifest used to be treated as cache-first alongside the
// hashed bundles/fonts/icons (see the fetch handler's "immutable by name"
// comment) — but its filename never changes while its content does (the
// per-environment __APP_TITLE__ substitution), so an already-installed SW
// kept serving a stale manifest indefinitely even after a redeploy changed
// it. Bumping VERSION here purges that stale cache for existing installs;
// see the manifest-specific network-first branch below for the actual fix.
const VERSION = 'v2';
const SHELL_CACHE = `redinfo-shell-${VERSION}`;
const DEV = new URLSearchParams(self.location.search).has('dev');

/**
 * What the shell needs to render at all.
 *
 * The hashed JS and CSS bundles are deliberately absent: their names change
 * every build, so they are cached as they are fetched instead. Listing them here
 * would mean regenerating this file on every deploy.
 */
const SHELL = [
  '/',
  '/index.html',
  '/manifest.webmanifest',
  '/fonts/inter.css',
  '/fonts/inter-latin.woff2',
  '/fonts/inter-latin-ext.woff2',
  '/logo-red-cross.svg',
  '/favicon.svg',
  '/icons/icon-192.png',
  '/icons/icon-512.png',
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      if (!DEV) {
        const cache = await caches.open(SHELL_CACHE);
        // Individually, and forgivingly: one asset renamed must not leave the whole
        // shell uncached, which is what `cache.addAll` would do.
        await Promise.all(
          SHELL.map((url) => cache.add(new Request(url, { cache: 'reload' })).catch(() => undefined)),
        );
      }
      // Live immediately. A crew who has just installed the app and walked out of
      // coverage cannot wait for every tab to close first.
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names.filter((name) => name !== SHELL_CACHE).map((name) => caches.delete(name)),
      );
      await self.clients.claim();
    })(),
  );
});

/**
 * One rule per kind of request, and the order matters.
 *
 * Anything that is not a same-origin GET is passed straight through: a PUT of a
 * run must never be served from a cache, and a cross-origin request (Maps, a
 * font we failed to self-host) is none of our business.
 */
self.addEventListener('fetch', (event) => {
  // Dev: unbundled source under Vite's dev server, changing on every save.
  // Caching it (or serving a cached offline shell for it) is the one thing
  // this worker must not do here — let every request go straight to network.
  if (DEV) return;

  const { request } = event;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // The API is never cached — see the note at the top of this file.
  if (isApiPath(url.pathname)) return;

  // A navigation is answered from the network when there is one and from the
  // cached shell when there is not. This is what makes `/live/<id>/scene` open
  // offline: the SPA's router resolves the path once the shell is running, so
  // any route falls back to the same document.
  if (request.mode === 'navigate') {
    event.respondWith(
      (async () => {
        try {
          return await fetch(request);
        } catch {
          const cache = await caches.open(SHELL_CACHE);
          return (
            (await cache.match('/index.html')) ??
            (await cache.match('/')) ??
            Response.error()
          );
        }
      })(),
    );
    return;
  }

  // manifest.webmanifest is the one shell entry whose *filename* never
  // changes but whose *content* does (the per-environment __APP_TITLE__
  // substitution baked in at build time). Cache-first would pin an
  // already-installed SW to whatever title was live when it first cached
  // this file. Network-first (falling back to the cached copy only when
  // offline, same shape as the navigate branch above) keeps it current on
  // every deploy while still working with no network.
  if (url.pathname === '/manifest.webmanifest') {
    event.respondWith(
      (async () => {
        const cache = await caches.open(SHELL_CACHE);
        try {
          const response = await fetch(request, { cache: 'no-store' });
          if (response.ok) void cache.put(request, response.clone());
          return response;
        } catch {
          return (await cache.match(request)) ?? Response.error();
        }
      })(),
    );
    return;
  }

  // Everything else — the hashed bundles, the fonts, the icons — is cache-first:
  // they are immutable by name, so a hit is always correct and always faster.
  event.respondWith(
    (async () => {
      const cache = await caches.open(SHELL_CACHE);
      const hit = await cache.match(request);
      if (hit) return hit;

      try {
        const response = await fetch(request);
        // Only a real, complete answer is worth keeping. A 404 or an opaque
        // response cached here would outlive the deploy that caused it.
        if (response.ok && response.type === 'basic') {
          void cache.put(request, response.clone());
        }
        return response;
      } catch (cause) {
        // Nothing cached and no network. Let the page decide what to show.
        throw cause;
      }
    })(),
  );
});

/** The paths the backend owns. Never cached, never intercepted. */
function isApiPath(pathname) {
  return (
    pathname.startsWith('/api/') ||
    pathname.startsWith('/auth/') ||
    pathname.startsWith('/live-runs') ||
    pathname.startsWith('/event-reports')
  );
}

/**
 * Web Push (#165) — a notice's title/body, shown as a system notification.
 * The payload is plain JSON (`{ title, body }`, see `EmailChannelService`'s
 * sibling `WebPushChannelService`), not the Push API's binary/encrypted
 * envelope — the browser has already decrypted it by the time this fires.
 */
self.addEventListener('push', (event) => {
  if (!event.data) return;
  let payload;
  try {
    payload = event.data.json();
  } catch {
    return;
  }
  event.waitUntil(
    self.registration.showNotification(payload.title ?? '', {
      body: payload.body,
      icon: '/icons/icon-192.png',
    }),
  );
});

/** Focuses an already-open tab rather than opening a second one, where possible. */
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  event.waitUntil(
    (async () => {
      const clientList = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
      const existing = clientList.find((client) => 'focus' in client);
      if (existing) {
        await existing.focus();
        return;
      }
      await self.clients.openWindow('/my-notices');
    })(),
  );
});
